parameters.text:
=Analyse the following fictional test company using only the information below.

Company:     {{ $('Test Company').first().json.company_name }}
Domain:      {{ $('Test Company').first().json.domain }}
Industry:    {{ $('Test Company').first().json.industry }}
Description: {{ $('Test Company').first().json.description }}

No other information is available. There is no website to read, no careers page,
no public repositories, no engineering blog and no job adverts. Everything not
stated above is unknown.

Return the JSON object described in the system message, and nothing else.

parameters.jsCode:
// Validate the Ollama response. This node never throws: it classifies the
// response and lets the IF node route. Malformed output is never repaired -
// no fence stripping, no key coercion, no defaults filled in.

const REQUIRED = {
  company_summary: 'string',
  facts: 'array',
  reasonable_inferences: 'array',
  unknown: 'array',
  technology: 'array',
  potential_devops_pain: 'array',
  recommended_service: 'string',
  confidence: 'number',
};

// Matches agents/research/schema.json.
const SERVICES = [
  'infrastructure_audit',
  'devops_improvement_sprint',
  'fractional_devops_sre',
  'none',
];

const test = $('Test Company').first().json;
const llm = $input.first().json ?? {};
const raw = typeof llm.text === 'string' ? llm.text : JSON.stringify(llm);

const errors = [];
const warnings = [];
let parsed = null;

if (!raw || raw.trim() === '') {
  errors.push('Model returned an empty response');
} else {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    errors.push('Response is not valid JSON: ' + e.message);
  }
}

if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
  errors.push('Response is valid JSON but not a JSON object');
  parsed = null;
}

if (parsed !== null) {
  for (const key of Object.keys(REQUIRED)) {
    const kind = REQUIRED[key];
    if (!(key in parsed)) {
      errors.push('Missing required key: ' + key);
      continue;
    }
    const value = parsed[key];
    const isArray = Array.isArray(value);
    const ok = kind === 'array' ? isArray : typeof value === kind && !isArray;
    if (!ok) {
      errors.push(
        'Key ' + key + ' must be ' + kind + ', got ' + (isArray ? 'array' : typeof value),
      );
      continue;
    }
    if (kind === 'array' && value.some((entry) => typeof entry !== 'string')) {
      errors.push('Key ' + key + ' must contain only strings');
    }
  }

  if (typeof parsed.confidence === 'number') {
    if (!Number.isFinite(parsed.confidence) || parsed.confidence < 0 || parsed.confidence > 1) {
      errors.push('confidence must be a number between 0 and 1, got ' + parsed.confidence);
    }
  }

  // Non-fatal: recorded on the run, does not fail the smoke test.
  const extra = Object.keys(parsed).filter((key) => !(key in REQUIRED));
  if (extra.length) {
    warnings.push('Unexpected keys present: ' + extra.join(', '));
  }
  if (typeof parsed.recommended_service === 'string' && !SERVICES.includes(parsed.recommended_service)) {
    warnings.push('recommended_service "' + parsed.recommended_service + '" is outside the agreed enum');
  }
}

const valid = errors.length === 0;

return [
  {
    json: {
      run_id: test.run_id,
      valid,
      failure_stage: valid ? null : 'validation',
      errors,
      warnings,
      error_message: valid ? null : 'Response validation failed: ' + errors.join('; '),
      parsed: valid ? parsed : null,
      raw_response: raw,
    },
  },
];

// The Ollama call itself failed (unreachable, model missing, timeout).
// Normalise the error into the same shape the validator produces so both
// failure paths can share one PostgreSQL node.

const test = $('Test Company').first().json;
const item = $input.first().json ?? {};

const candidate = item.error ?? item.message ?? 'Ollama call failed with no error message';
const message =
  typeof candidate === 'string'
    ? candidate
    : (candidate && typeof candidate.message === 'string')
      ? candidate.message
      : JSON.stringify(candidate);

return [
  {
    json: {
      run_id: test.run_id,
      valid: false,
      failure_stage: 'llm_call',
      errors: [message],
      warnings: [],
      error_message: 'Ollama call failed: ' + message,
      parsed: null,
      raw_response: null,
    },
  },
];
